INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "薛融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：薛融，自述者。", "biography": null, "status": "draft", "id": "88010995-da61-5a9b-b48e-735ca607d915"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "经铸（后晋金部郎中）", "aliases": ["经铸", "經鑄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋金部郎中。938年六月奏请调整垦田农户承担徭役的条件，石敬瑭接受建议。姓名沿《资治通鉴》电子底本，生卒年和其他经历未载。", "biography": null, "status": "draft", "id": "b84e6cc0-9598-5d6c-8c93-393b20bfde04"}, {"name": "吕琦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：吕琦。", "biography": null, "status": "draft", "id": "8ffb1307-35a3-50aa-b656-645eee4c0395"}, {"name": "刘皞（后晋编敕官）", "aliases": ["刘皞", "劉皞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。《旧五代史》记载，938年七月以驾部员外郎兼侍御史知杂事的身份参与编订唐明宗时期的诏敕。生卒年未载。", "biography": null, "status": "draft", "id": "c44bce1e-a8e2-5c68-adc3-bc8a4c48978f"}, {"name": "司徒诩", "aliases": ["司徒詡"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：司徒诩，病告半年者。", "biography": null, "status": "draft", "id": "656dbdcb-bb8b-591c-8b1d-df97e69cded9"}, {"name": "张仁彖（后晋大理正）", "aliases": ["张仁彖", "張仁彖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋大理正。《旧五代史》记载，938年七月参与编订唐明宗时期的诏敕。生卒年未载。", "biography": null, "status": "draft", "id": "86474483-a696-5998-9541-9f95d3b8472d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "高行周奏请修缮洛阳宫", "start_year": null, "end_year": null, "time_original": "938年六月丙戌薛融进谏之前，奏请的具体日期未载", "dynasty": "五代十国", "description": "高行周奏请修缮洛阳宫。", "phases": [], "location_name": "洛阳宫", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "be6d3553-4a69-503d-a2d4-0b1807ac9339"}, {"title": "薛融建议暂缓修缮洛阳宫", "start_year": 938, "end_year": 938, "time_original": "938年六月丙戌", "dynasty": "五代十国", "description": "薛融指出魏城尚未攻下、国家和百姓都处于困窘之中，建议等局势安定后再修缮洛阳宫。", "phases": [], "location_name": "洛阳宫", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9aa282b4-c74f-5ffe-bec8-e0eaed893bc4"}, {"title": "石敬瑭接受薛融的建议，并下诏表扬他", "start_year": 938, "end_year": 938, "time_original": "938年六月丙戌条下", "dynasty": "五代十国", "description": "石敬瑭接受薛融的建议，并下诏表扬他。", "phases": [], "location_name": "洛阳宫", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "394d1fa7-19c2-5a46-8310-3d4f28e6a071"}, {"title": "洛阳宫的修缮工程随后停止", "start_year": null, "end_year": null, "time_original": "薛融进谏获接受之后，具体日期未载", "dynasty": "五代十国", "description": "洛阳宫的修缮工程随后停止。", "phases": [], "location_name": "洛京大内", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3318ce11-9779-5504-a38e-ea012e2b2209"}, {"title": "经铸报告垦田农户被过早征派徭役的问题", "start_year": 938, "end_year": 938, "time_original": "938年六月己丑", "dynasty": "五代十国", "description": "经铸报告，有些流动农户愿意耕种定居，却在种树未满十年、垦田未到三顷时，就被县里征派徭役、催缴重赋，因而放弃经营并考虑迁往别处。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "edc6f23d-076f-57eb-b687-e8c6d7ad4784"}, {"title": "经铸建议调整垦田农户承担徭役的条件", "start_year": 938, "end_year": 938, "time_original": "938年六月己丑", "dynasty": "五代十国", "description": "经铸建议，今后农户垦田达到五顷以上，三年之后才允许县里征派徭役。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "272d08ea-9cca-54ea-8bc9-c11b5c8dfe6b"}, {"title": "石敬瑭接受经铸调整徭役条件的建议", "start_year": 938, "end_year": 938, "time_original": "938年六月己丑条下", "dynasty": "五代十国", "description": "石敬瑭接受经铸的建议：农户垦田达到五顷以上，三年之后才允许县里征派徭役。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d9fab714-beb9-5e4c-932b-3734c20a3f67"}, {"title": "中书建议整理唐明宗时期和清泰年间的诏敕", "start_year": 938, "end_year": 938, "time_original": "938年七月，奏请的具体日期未载", "dynasty": "五代十国", "description": "中书建议派官员收集唐明宗时期和清泰年间的诏敕，选出可以长期施行的条文，整理编订。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6b4d4cd9-abdf-57ee-892e-e5a0b8e7398f"}, {"title": "石敬瑭命薛融等官员审核编订旧诏敕", "start_year": 938, "end_year": 938, "time_original": "938年七月己酉", "dynasty": "五代十国", "description": "石敬瑭命左谏议大夫薛融等官员审核编订唐明宗时期和清泰年间的诏敕。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0d68373c-f4b9-5a91-a5e7-dfac09bf068c"}, {"title": "石敬瑭下令制作受命宝", "start_year": 938, "end_year": 938, "time_original": "938年七月辛酉", "dynasty": "五代十国", "description": "石敬瑭下令制作受命宝，印文为“受天明命，惟德允昌”。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e087982a-aeae-5b9b-866d-f0b450766321"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

